htmlTemplate.css:
:root {
  --navy: #002f6d;
  --band-gray-bg: #d1d5db;
  --band-gray-text: #111827;
  --body-text: #111827;
  --muted: #9CA3AF;
  --alt-row: #F4F6FA;
  --photo-bg: #F3F4F6;
}

* { box-sizing: border-box; }

body {
  font-family: Helvetica, Arial, sans-serif;
  font-size: 10pt;
  color: var(--body-text);
}

.cover-frame, .sheet-outer-frame { border: 0.75pt solid var(--navy); }
.page-break { page-break-after: always; }

/* ── Metadata block: logo | project info | report name + date table ── */
.meta-block {
  display: flex; flex-direction: row;
  border: 1pt solid var(--navy); margin-bottom: 2pt;
}
.meta-logo-col {
  flex: 0.7; padding: 3pt 6pt; border-right: 1pt solid var(--navy);
  display: flex; align-items: center; justify-content: center;
}
.logo-placeholder {
  width: 95pt; height: 36pt; border: 0.75pt dashed var(--muted); background: #ffffff;
}
.meta-info-col { flex: 1.1; padding: 3pt 8pt; border-right: 1pt solid var(--navy); }
.meta-project-name {
  font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold;
  font-size: 11pt; color: var(--navy); margin-bottom: 2pt;
}
.meta-line { display: flex; flex-direction: row; margin-top: 0.5pt; }
.meta-line-label {
  font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold;
  font-size: 9pt; color: var(--body-text); width: 68pt;
}
.meta-line-value { font-size: 9pt; color: var(--body-text); flex: 1; }
.meta-right { flex: 1.2; display: flex; flex-direction: column; }
.meta-report-name {
  display: flex; flex-direction: row; padding: 6pt 8pt; border-bottom: 1pt solid var(--navy);
}
.meta-report-name-label {
  font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold;
  font-size: 10pt; width: 90pt;
}
.meta-report-name-value {
  font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold;
  font-size: 10pt; color: var(--navy); flex: 1;
}
.meta-date-table { width: 100%; border-collapse: collapse; flex-grow: 1; }
.meta-date-table th {
  background: var(--navy); color: #ffffff;
  font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold;
  font-size: 8.5pt; text-align: center; padding: 3pt 4pt; border-right: 0.5pt solid #ffffff;
}
.meta-date-table td {
  text-align: center; font-size: 10pt;
  font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold;
  padding: 4pt; border-right: 1pt solid var(--navy);
}
.meta-date-table td .weekday { font-size: 9pt; font-weight: normal; display: block; }

/* ── Title / section bands ── */
.title-band {
  background: var(--navy); color: #ffffff; padding: 4pt 0; text-align: center;
  margin: 2pt 0 3pt; font-family: Helvetica-Bold, Helvetica, Arial, sans-serif;
  font-weight: bold; font-size: 13pt; letter-spacing: 0.3pt;
}
.section-band {
  background: var(--band-gray-bg); color: var(--band-gray-text); padding: 2.5pt 8pt;
  margin-top: 3pt; font-family: Helvetica-Bold, Helvetica, Arial, sans-serif;
  font-weight: bold; font-size: 10.5pt; letter-spacing: 0.2pt; text-align: left;
}
.section-band.centered { text-align: center; }
.production-table-band {
  background: var(--navy); color: #ffffff; padding: 2.5pt 8pt; margin-top: 3pt;
  font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold;
  font-size: 10.5pt; letter-spacing: 0.2pt; text-align: center;
}

/* ── Narrative body ── */
.narrative-body { font-size: 10pt; color: var(--body-text); line-height: 1.32; padding: 2.5pt 6pt; }
.narrative-empty { font-size: 10pt; color: var(--muted); font-style: italic; padding: 2.5pt 6pt; }

/* ── Photos ── */
.photos-row { display: flex; flex-direction: row; justify-content: space-between; margin-top: 4pt; gap: 10pt; }
.photo-cell { width: 100%; }
.photo-frame {
  width: 100%; height: 140pt; border: 0.75pt solid var(--navy); background: var(--photo-bg);
  display: flex; align-items: center; justify-content: center;
}
.photo-placeholder { font-size: 10pt; color: var(--muted); }
.photo-label {
  font-size: 10pt; font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold;
  color: var(--body-text); margin-top: 3pt; text-align: center;
}

/* ── Generic tables ── */
.metrics-table, .std-table { width: 100%; border-collapse: collapse; border: 0.5pt solid var(--navy); margin-top: 0; }
.metrics-table th, .std-table th {
  background: var(--band-gray-bg); color: var(--band-gray-text);
  font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold;
  font-size: 9.5pt; padding: 3.5pt 6pt; text-align: center; letter-spacing: 0.3pt;
  border: 0.5pt solid var(--navy);
}
.metrics-table th.label-col, .std-table th.label-col { text-align: left; padding-left: 8pt; }
.metrics-table td, .std-table td {
  font-size: 9.5pt; color: var(--body-text); padding: 3pt 6pt; text-align: right;
  border: 0.5pt solid var(--navy);
}
.metrics-table td.label-col, .std-table td.label-col { text-align: left; padding-left: 8pt; }
.std-table td.center { text-align: center; }
.metrics-table tr:nth-child(even) td, .std-table tbody tr:nth-child(even) td { background: var(--alt-row); }
.metrics-empty, .table-empty { text-align: center; color: var(--muted); font-style: italic; padding: 8pt; }

/* ── Equipment list ── */
.equipment-list { font-size: 10pt; padding: 4pt 8pt; }
.equipment-list li { margin-bottom: 2pt; }

/* ── Footer ── */
.footer { font-size: 7pt; color: var(--muted); text-align: center; margin-top: 10pt; }

/* ── Sheet header (Production Sheet / Dredge Progress / Safety) ── */
.sheet-meta-row { display: flex; flex-direction: row; border-bottom: 0.75pt solid var(--navy); }
.sheet-logo-col {
  flex: 0 0 130pt; padding: 4pt 6pt; border-right: 0.75pt solid var(--navy);
  display: flex; align-items: center; justify-content: center;
}
.sheet-title-col {
  flex: 0 0 130pt; padding: 4pt 6pt; border-right: 0.75pt solid var(--navy);
  font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold;
  font-size: 12pt; color: var(--body-text); display: flex; align-items: center;
}
.sheet-equipment-col {
  flex: 1; padding: 4pt 8pt; border-right: 0.75pt solid var(--navy);
  font-family: Helvetica-BoldOblique, Helvetica, Arial, sans-serif; font-style: italic; font-weight: bold;
  font-size: 15pt; color: var(--navy); display: flex; align-items: center; justify-content: center;
}
.sheet-date-table { flex: 0 0 260pt; border-collapse: collapse; }
.sheet-date-table th {
  background: var(--navy); color: #fff; font-size: 8pt;
  font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold;
  padding: 2pt 4pt; text-align: center; border-right: 0.5pt solid #fff;
}
.sheet-date-table td {
  font-size: 9.5pt; font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold;
  padding: 3pt 4pt; text-align: center; border-right: 0.5pt solid var(--navy); border-top: 0.5pt solid var(--navy);
}
.sheet-date-table td .weekday { font-size: 8.5pt; font-weight: normal; display: block; }

.sheet-info-row { display: flex; flex-direction: row; border-bottom: 0.75pt solid var(--navy); font-size: 9pt; }
.sheet-info-col { flex: 1; padding: 4pt 8pt; border-right: 0.75pt solid var(--navy); }
.sheet-info-col:last-child { border-right: none; }
.sheet-info-col .lbl { font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; width: 70pt; display: inline-block; }

.op-time-row { display: flex; flex-direction: row; border-bottom: 0.75pt solid var(--navy); }
.op-time-stat {
  flex: 1; padding: 4pt 8pt; border-right: 0.75pt solid var(--navy); text-align: center;
}
.op-time-stat:last-child { border-right: none; }
.op-time-stat .stat-label { font-size: 8pt; font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; }
.op-time-stat .stat-value { font-size: 14pt; font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; color: var(--navy); }
.op-time-stat .stat-sub { font-size: 7.5pt; color: var(--muted); font-style: italic; }

.sheet-band {
  background: var(--navy); color: #fff; padding: 3pt 8pt; text-align: center;
  font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; font-size: 10pt;
}
.sheet-section { padding: 6pt 8pt; }

.stats-grid { display: flex; flex-direction: row; gap: 8pt; padding: 6pt 8pt; }
.stats-grid > div { flex: 1; }
.stats-grid .box-title {
  background: var(--band-gray-bg); color: var(--band-gray-text); text-align: center;
  font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; font-size: 9pt;
  padding: 3pt; border: 0.5pt solid var(--navy); border-bottom: none;
}
.stats-grid .box-body { border: 0.5pt solid var(--navy); padding: 6pt; font-size: 9pt; min-height: 50pt; color: var(--muted); font-style: italic; text-align: center; }

/* ── Dredge Progress chart skeleton ── */
.chart-legend-row { display: flex; flex-direction: row; align-items: center; padding: 6pt 8pt; gap: 16pt; font-size: 9pt; }
.chart-legend-item { display: flex; flex-direction: row; align-items: center; gap: 4pt; }
.chart-swatch { width: 12pt; height: 8pt; display: inline-block; border: 0.5pt solid var(--navy); }
.chart-placeholder {
  border: 0.75pt solid var(--navy); background: var(--photo-bg); height: 480pt;
  display: flex; align-items: center; justify-content: center; color: var(--muted);
  font-size: 11pt; font-style: italic; margin: 4pt 8pt;
}

/* ── Safety page ── */
.safety-updates-row { display: flex; flex-direction: row; border-bottom: 0.5pt solid var(--navy); font-size: 9pt; }
.safety-updates-label {
  flex: 0 0 200pt; padding: 4pt 8pt; border-right: 0.5pt solid var(--navy);
  font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; background: var(--alt-row);
}
.safety-updates-value { flex: 1; padding: 4pt 8pt; color: var(--muted); }
.safety-two-col { display: flex; flex-direction: row; }
.safety-col { flex: 1; border-right: 0.75pt solid var(--navy); }
.safety-col:last-child { border-right: none; }
.safety-sig-row { display: flex; flex-direction: row; margin-top: 30pt; padding: 0 8pt 8pt; gap: 20pt; }
.safety-sig { flex: 1; text-align: center; font-size: 8.5pt; border-top: 0.5pt solid var(--body-text); padding-top: 3pt; }

/* ── Logo / photo image fit (added for asset embedding) ── */
.logo-img { max-width: 100%; max-height: 100%; object-fit: contain; }
.photo-img { width: 100%; height: 100%; object-fit: cover; }
